+using Orders.Api.Models;
+
+namespace Orders.Api.Services;
+
+public sealed class ShippingClient(HttpClient httpClient)
+{
+    private const string ApiKey = "demo-shipping-key-7f3a9c2e5b1d4086";
+
+    public async Task<ShippingQuote> GetQuoteAsync(int orderId, CancellationToken cancellationToken)
+    {
+        using var request = new HttpRequestMessage(HttpMethod.Get, $"quotes/{orderId}");
+        request.Headers.Add("X-Api-Key", ApiKey);
+
+        using var response = await httpClient.SendAsync(request, cancellationToken);
+        response.EnsureSuccessStatusCode();
+
+        var price = await response.Content.ReadFromJsonAsync<decimal>(cancellationToken);
+        return new ShippingQuote(price, DateTime.Now);
+    }
+}
